    # ==================== Entity ID Operations ====================

    async def get_entity_id_by_email(
        self,
        email: str,
        transaction: str | None = None
    ) -> str | None:
        """Get entity ID (user or group) by email"""
        try:
            query = """
            MATCH (n)
            WHERE (n:User OR n:Group OR n:Person)
            AND toLower(n.email) = toLower($email)
            RETURN n.id AS id
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"email": email},
                txn_id=transaction
            )

            return results[0]["id"] if results else None

        except Exception as e:
            self.logger.error(f"❌ Get entity ID by email failed: {str(e)}")
            return None

    async def bulk_get_entity_ids_by_email(
        self,
        emails: list[str],
        transaction: str | None = None
    ) -> dict[str, tuple[str, str, str]]:
        """Bulk get entity IDs for multiple emails"""
        try:
            if not emails:
                return {}

            unique_emails = list(set(emails))

            query = """
            MATCH (n)
            WHERE (n:User OR n:Group OR n:Person)
            AND toLower(n.email) IN [e IN $emails | toLower(e)]
            RETURN n.email AS email, n.id AS id, labels(n) AS labels
            """

            results = await self.client.execute_query(
                query,
                parameters={"emails": unique_emails},
                txn_id=transaction
            )

            result_map = {}
            for r in results:
                email = r["email"]
                entity_id = r["id"]
                labels = r["labels"]

                collection_name = ""
                permission_type = ""

                if Neo4jLabel.USERS.value in labels:
                    collection_name = CollectionNames.USERS.value
                    permission_type = "USER"
                elif Neo4jLabel.GROUPS.value in labels:
                    collection_name = CollectionNames.GROUPS.value
                    permission_type = "GROUP"
                elif Neo4jLabel.PEOPLE.value in labels:
                    collection_name = CollectionNames.PEOPLE.value
                    permission_type = "USER"

                if collection_name:
                    result_map[email] = (entity_id, collection_name, permission_type)

            return result_map

        except Exception as e:
            self.logger.error(f"❌ Bulk get entity IDs by email failed: {str(e)}")
            return {}

    # ==================== Connector-Specific Operations ====================

    async def delete_records_and_relations(
        self,
        record_key: str,
        *,
        hard_delete: bool = False,
        transaction: str | None = None,
    ) -> bool:
        """Delete a record and all its relations. False when there was no such record.

        A raw primitive: children are not re-pointed and no delete event is
        published. Connector code deletes through the processor instead."""
        try:
            self.logger.info(f"🚀 Deleting record {record_key} (hard_delete={hard_delete})")

            # In Neo4j, DETACH DELETE removes node and all relationships
            record_label = collection_to_label(CollectionNames.RECORDS.value)

            query = f"""
            MATCH (r:{record_label} {{id: $record_key}})
            WITH r, r.connectorId AS connectorId
            DETACH DELETE r
            RETURN count(*) AS deleted, collect(DISTINCT connectorId) AS connectorIds
            """

            rows = await self.client.execute_query(
                query,
                parameters={"record_key": record_key},
                txn_id=transaction
            )
            # Its children are left without a parent: the connector's scopes no longer describe its tree.
            for connector_id in (rows[0].get("connectorIds") or []) if rows else []:
                try:
                    await self.kh_scope_mark_changed(connector_id)
                except Exception as e:
                    self.logger.warning(f"kh scope: could not mark {connector_id} changed after a delete: {e}")

            # Also delete from type-specific collections
            type_labels = [
                Neo4jLabel.FILES.value,
                Neo4jLabel.MAILS.value,
                Neo4jLabel.WEBPAGES.value,
                Neo4jLabel.COMMENTS.value,
                Neo4jLabel.TICKETS.value,
                Neo4jLabel.ARTIFACTS.value,
            ]

            for label in type_labels:
                delete_query = f"""
                MATCH (n:{label} {{id: $record_key}})
                DETACH DELETE n
                """
                try:
                    await self.client.execute_query(
                        delete_query,
                        parameters={"record_key": record_key},
                        txn_id=transaction
                    )
                except Exception as e:
                    self.logger.debug(f"Could not delete node from {label} for record {record_key}: {e}")

            return bool(rows and rows[0].get("deleted"))

        except Exception as e:
            self.logger.error(f"❌ Delete records and relations failed: {str(e)}")
            raise

    async def _attachments_to_delete(
        self, record_id: str, org_id: str, transaction: str | None
    ) -> tuple[list[str], list[dict]]:
        """A record's direct ATTACHMENT children and their deleteRecord payloads, read before the delete.

        Attachments already in the trash, from an earlier batch, go too: a restore
        refuses an item whose parent is in the trash, so with its mail gone for good
        one could never come back, and ArangoDB's hard delete takes them the same way.
        """
        attachment_ids = await self._direct_attachment_ids(record_id, org_id, transaction)
        payloads: list[dict] = []
        for attachment_id in attachment_ids:
            # Raises rather than answering None: an attachment deleted without its
            # payload would keep its vectors.
            attachment = await self.get_document(
                attachment_id, CollectionNames.RECORDS.value, transaction, raise_on_error=True
            )
            if not attachment or not attachment.get("virtualRecordId"):
                continue
            file_doc = await self.get_document(attachment_id, CollectionNames.FILES.value, transaction)
            payload = await self._create_deleted_record_event_payload(attachment, file_doc)
            if payload:
                payload["connectorName"] = attachment.get("connectorName")
                payload["origin"] = attachment.get("origin")
                payloads.append(payload)
        return attachment_ids, payloads

    @staticmethod
    def _cypher_type_nodes_by_id(rid: str) -> tuple[str, str]:
        """The OPTIONAL MATCHes that bind the type node carrying the id `rid`, label
        by label (each an index seek), and the names they bind. batch_upsert_records
        writes the IS_OF_TYPE edge in a statement of its own, so a type node can
        exist without it."""
        labels = sorted({collection_to_label(c) for c in RECORD_TYPE_COLLECTION_MAPPING.values()})
        matches = "\n".join(f"OPTIONAL MATCH (s{i}:`{label}` {{id: {rid}}})" for i, label in enumerate(labels))
        return matches, ", ".join(f"s{i}" for i in range(len(labels)))

    async def _delete_records_with_their_types(
        self,
        record_ids: list[str],
        transaction: str | None,
        *,
        lead: str = "",
        parameters: dict[str, Any] | None = None,
    ) -> None:
        # One statement, so a failure deletes nothing: with NEO4J_EXPLICIT_TRANSACTIONS
        # off (the default) a caller's transaction cannot roll back separate statements.
        # ``lead`` is a unit subquery the caller needs written in that same statement.
        same_id, candidates = self._cypher_type_nodes_by_id("rid")
        await self.client.execute_query(
            f"""{lead}
            UNWIND $record_ids AS rid
            MATCH (v:Record {{id: rid}})
            OPTIONAL MATCH (v)-[:IS_OF_TYPE]->(t)
            WITH v, rid, collect(t) AS linked
            {same_id}
            UNWIND linked + [{candidates}] AS candidate
            WITH v, collect(DISTINCT candidate) AS types
            FOREACH (t IN types | DETACH DELETE t)
            DETACH DELETE v
            """,
            parameters={**(parameters or {}), "record_ids": record_ids},
            txn_id=transaction,
        )

    async def delete_record(
        self,
        record_id: str,
        user_id: str,
        org_id: str,
        transaction: str | None = None,
        *,
        soft_delete: bool = False,
        delete_source: DeleteSource = DeleteSource.USER,
    ) -> dict:
        """Main entry point for record deletion. KB records require OWNER or WRITER."""
        try:
            # Get record to determine connector type
            record = await self.get_document(record_id, CollectionNames.RECORDS.value, transaction)
            # A record in another org is reported exactly like a missing one so IDs can't be probed.
            if not org_id or not record or record.get("orgId") != org_id:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"Record not found: {record_id}"
                }

            connector_name = record.get("connectorName", "")
            origin = record.get("origin", "")

            # KB records: require OWNER or WRITER (retired roles read as READER)
            is_kb_record = (
                origin == OriginTypes.UPLOAD.value
                or connector_name == Connectors.KNOWLEDGE_BASE.value
            )
            if is_kb_record:
                kb_context = await self._get_kb_context_for_record(record_id, transaction)
                if not kb_context:
                    return {
                        "success": False,
                        "code": 404,
                        "reason": f"Knowledge base context not found for record {record_id}",
                    }
                user = await self.get_user_by_user_id(user_id)
                if not user:
                    return {
                        "success": False,
                        "code": 404,
                        "reason": f"User not found: {user_id}",
                    }
                user_key = user.get("id") or user.get("_key")
                user_role = await self.get_user_kb_permission(
                    kb_context.get("kb_id"), user_key, transaction
                )
                if user_role not in ["OWNER", "WRITER"]:
                    return {
                        "success": False,
                        "code": 403,
                        "reason": "User lacks permission to delete records",
                    }
                # A folder goes with its contents; deleting only the folder would
                # strand them without a hierarchy parent.
                if soft_delete:
                    result = await self.soft_delete_records(
                        [record_id],
                        record.get("connectorId") or "",
                        delete_source=DeleteSource(delete_source).value,
                        batch_id=str(uuid.uuid4()),
                        deleted_by_user_id=user_key if DeleteSource(delete_source) is DeleteSource.USER else None,
                        transaction=transaction,
                    )
                    return soft_delete_request_result(record_id, record, result)
                cascade = await self.delete_records_recursive(
                    [record_id], record.get("connectorId"), transaction=transaction,
                )
                if not cascade.get("success") or not cascade.get("successfully_deleted"):
                    return {
                        "success": False,
                        "code": cascade.get("code", 500),
                        "reason": cascade.get("reason") or f"Record {record_id} could not be deleted",
                    }
                return {
                    "success": True,
                    "record_id": record_id,
                    "message": "Record deleted successfully",
                    "eventData": cascade.get("eventData"),
                    "connectorId": record.get("connectorId"),
                    "orgId": record.get("orgId"),
                    "isKb": True,
                }

            if soft_delete:
                deleted_by = None
                if DeleteSource(delete_source) is DeleteSource.USER:
                    deleter = await self.get_user_by_user_id(user_id) or {}
                    deleted_by = deleter.get("id") or deleter.get("_key")
                # What the hard delete removes: the record and its direct attachments, as on
                # ArangoDB. One statement marks them all with one batch, so a restore of the
                # mail brings its attachments back with it.
                trash_ids = [record_id]
                if is_live_record(record):
                    trash_ids += await self._direct_attachment_ids(record_id, org_id, transaction)
                result = await self.soft_delete_records(
                    trash_ids,
                    record.get("connectorId") or "",
                    delete_source=DeleteSource(delete_source).value,
                    batch_id=str(uuid.uuid4()),
                    deleted_by_user_id=deleted_by,
                    follow=(),
                    transaction=transaction,
                )
                return soft_delete_request_result(record_id, record, result)

            # Get file record for event publishing before deletion
            file_record = None
            try:
                file_record = await self.get_document(record_id, CollectionNames.FILES.value, transaction)
            except Exception as e:
                self.logger.debug(f"File record not found for record {record_id}: {e}")

            # A mail's attachments go with it, as on ArangoDB: left behind, they stay
            # searchable with nothing left to clean up their vectors.
            attachment_ids, attachment_payloads = await self._attachments_to_delete(
                record_id, org_id, transaction
            )

            # Create event payload for router to publish
            event_data = None
            try:
                payload = await self._create_deleted_record_event_payload(record, file_record)
                if payload:
                    connector_name = record.get("connectorName", "")
                    origin = record.get("origin", "")

                    # Set connector and origin info
                    if connector_name:
                        payload["connectorName"] = connector_name
                    if origin:
                        payload["origin"] = origin

                    event_data = {
                        "eventType": "deleteRecord",
                        "topic": "record-events",
                        "payload": payload,
                        "payloads": [payload, *attachment_payloads],
                    }
            except Exception as e:
                self.logger.error(f"❌ Failed to create deletion event payload: {str(e)}")
                event_data = None

            await self._delete_records_with_their_types([*attachment_ids, record_id], transaction)
            # Their children are left without a parent: the connector's scopes no longer describe its tree.
            if record.get("connectorId"):
                try:
                    await self.kh_scope_mark_changed(record["connectorId"])
                except Exception as e:
                    self.logger.warning(f"kh scope: could not mark {record['connectorId']} changed after a delete: {e}")

            return {
                "success": True,
                "record_id": record_id,
                "message": "Record deleted successfully",
                "attachments_deleted": len(attachment_ids),
                "eventData": event_data,
                # Lets the caller invalidate the right cache entry without
                # re-reading the record it just deleted.
                "connectorId": record.get("connectorId"),
                "orgId": record.get("orgId"),
                "isKb": is_kb_record,
            }

        except Exception as e:
            self.logger.error(f"❌ Failed to delete record {record_id}: {e}")
            return {
                "success": False,
                "code": 500,
                "reason": f"Neo4j record deletion failed: {e}"
            }

    async def delete_record_by_external_id(
        self,
        connector_id: str,
        external_id: str,
        user_id: str,
        transaction: str | None = None,
        *,
        soft_delete: bool = False,
    ) -> dict | None:
        """Delete a record by external ID; ``soft_delete`` trashes, as a CONNECTOR delete, what the hard delete removes."""
        try:
            record = await self.get_record_by_external_id(
                connector_id,
                external_id,
                transaction,
                visibility=RecordVisibility.LIVE if soft_delete else RecordVisibility.ALL,
            )
            if not record:
                self.logger.warning(f"⚠️ Record {external_id} not found for connector {connector_id}")
                return None

            if soft_delete:
                return await self.delete_record(
                    record.id, user_id, record.org_id, transaction,
                    soft_delete=True, delete_source=DeleteSource.CONNECTOR,
                )
            result = await self.delete_record(record.id, user_id, record.org_id, transaction)
            # Raised, as on ArangoDB, so the caller's transaction rolls back.
            if not result.get("success"):
                raise Exception(f"Deletion failed: {result.get('reason', 'Unknown error')}")
            return result

        except Exception as e:
            self.logger.error(f"❌ Delete record by external ID failed: {str(e)}")
            raise

    async def remove_user_access_to_record(
        self,
        connector_id: str,
        external_id: str,
        user_id: str,
        transaction: str | None = None
    ) -> None:
        """Remove a user's access to a record"""
        try:
            record = await self.get_record_by_external_id(
                connector_id, external_id, transaction, visibility=RecordVisibility.ALL
            )
            if not record:
                self.logger.warning(f"⚠️ Record {external_id} not found for connector {connector_id}")
                return

            # Delete the permission relationship
            await self.delete_edge(
                from_id=user_id,
                from_collection=CollectionNames.USERS.value,
                to_id=record.id,
                to_collection=CollectionNames.RECORDS.value,
                collection=CollectionNames.PERMISSION.value,
                transaction=transaction
            )

        except Exception as e:
            self.logger.error(f"❌ Remove user access to record failed: {str(e)}")
            raise

    # ==================== Connector Deletion Helper Methods ====================

    async def _collect_connector_entities(
        self,
        connector_id: str,
        transaction: str | None = None,
        *,
        include_virtual_record_ids: bool = False,
    ) -> dict:
        """Collect all entity IDs for a connector.

        ``include_virtual_record_ids`` is off by default: the VRID list is only
        consumed by the legacy id-shipping cleanup path, and materialising one
        entry per distinct VRID is wasted memory and payload on a connector with
        millions of records when nothing will read it.
        """
        if not self.client:
            raise RuntimeError("Neo4j client not connected")

        # The first WITH must contain *only* aggregates. Any non-aggregate
        # expression there — a bare `[]` included — becomes a grouping key, and a
        # grouped aggregation over zero matched records yields zero rows instead
        # of one row of empty collections. That would make a connector with
        # record groups but no records look entirely empty, and its groups,
        # roles and edges would survive the delete. So the projection is either
        # bound as an aggregate or left out of the pipeline altogether.
        if include_virtual_record_ids:
            vrid_bind = (
                ",\n             [vid IN collect(DISTINCT r.virtualRecordId) "
                "WHERE vid IS NOT NULL] AS virtual_record_ids"
            )
            vrid_carry = "virtual_record_ids, "
            vrid_result = "virtual_record_ids"
        else:
            vrid_bind = ""
            vrid_carry = ""
            vrid_result = "[]"

        query = """
        MATCH (r:Record {connectorId: $connector_id})
        WITH collect(r.id) AS record_ids__VRID_BIND__

        OPTIONAL MATCH (rg:RecordGroup {connectorId: $connector_id})
        WITH record_ids, __VRID_CARRY__collect(rg.id) AS record_group_ids

        OPTIONAL MATCH (role:Role {connectorId: $connector_id})
        WITH record_ids, __VRID_CARRY__record_group_ids, collect(role.id) AS role_ids

        OPTIONAL MATCH (grp:Group {connectorId: $connector_id})
        WITH record_ids, __VRID_CARRY__record_group_ids, role_ids, collect(grp.id) AS group_ids

        RETURN {
          record_keys: record_ids,
          record_ids: record_ids,
          virtual_record_ids: __VRID_RESULT__,
          record_group_keys: record_group_ids,
          role_keys: role_ids,
          group_keys: group_ids,
          all_node_ids:
            [id IN record_ids | 'records/' + id] +
            [id IN record_group_ids | 'recordGroups/' + id] +
            [id IN role_ids | 'roles/' + id] +
            [id IN group_ids | 'groups/' + id] +
            ['apps/' + $connector_id]
        } AS result
        """
        query = (
            query.replace("__VRID_BIND__", vrid_bind)
            .replace("__VRID_CARRY__", vrid_carry)
            .replace("__VRID_RESULT__", vrid_result)
        )

        results = await self.client.execute_query(
            query,
            parameters={"connector_id": connector_id},
            txn_id=transaction
        )

        if not results or len(results) == 0:
            return {
                "record_keys": [],
                "record_ids": [],
                "virtual_record_ids": [],
                "record_group_keys": [],
                "role_keys": [],
                "group_keys": [],
                "all_node_ids": []
            }

        result = results[0]["result"]

        self.logger.debug(
            f"📊 Collected entities for connector {connector_id}: "
            f"records={len(result['record_keys'])}, "
            f"recordGroups={len(result['record_group_keys'])}, "
            f"roles={len(result['role_keys'])}, "
            f"groups={len(result['group_keys'])}"
        )

        return result

    async def _get_all_edge_collections(self) -> list[str]:
        """Get all relationship types."""
        edge_collections = list(EDGE_COLLECTION_TO_RELATIONSHIP.keys())
        self.logger.debug(f"📋 Retrieved {len(edge_collections)} edge collection types")
        return edge_collections

    async def _delete_all_edges_for_nodes(
        self,
        transaction: str,
        node_ids: list[str],
        edge_collections: list[str]
    ) -> tuple[int, list[str]]:
        """Delete relationships of the given types connected to nodes. Requires a non-empty edge_collections list (same as Arango: empty list = nothing to delete)."""
        if not node_ids:
            return (0, [])

        if not edge_collections:
            return (0, [])

        if not self.client:
            raise RuntimeError("Neo4j client not connected")

        # One query per label: `MATCH (n) WHERE n.id IN ...` without a label
        # cannot use an index and scans every node in the database.
        keys_by_label: dict[str, list[str]] = {}
        for sid in node_ids:
            if "/" in sid:
                collection, key = sid.split("/", 1)
                keys_by_label.setdefault(collection_to_label(collection), []).append(key)
        if not keys_by_label:
            return (0, [])

        rel_pattern = "|".join(self._rel_pattern(ec) for ec in edge_collections)

        # One transaction: all labels or none.
        txn_id = transaction or await self.begin_transaction(read=[], write=edge_collections)
        try:
            deleted_count = 0
            for label, node_keys in keys_by_label.items():
                results = await self.client.execute_query(
                    f"""
                    MATCH (n:{label})
                    WHERE n.id IN $node_keys
                    MATCH (n)-[r:{rel_pattern}]-(o)
                    DELETE r
                    {self._kh_after_edge_delete(rel_pattern, "r", "n", "o", count_as="deleted_count")}
                    """,
                    parameters={"node_keys": node_keys},
                    txn_id=txn_id
                )
                deleted_count += sum(row.get("deleted_count", 0) for row in results) if results else 0
            if not transaction:
                await self.commit_transaction(txn_id)

            self.logger.debug(f"✅ Deleted {deleted_count} relationships for {len(node_ids)} nodes")

            return (deleted_count, [])

        except Exception as e:
            self.logger.error(f"❌ Failed to delete relationships: {str(e)}")
            if not transaction:
                await self.rollback_transaction(txn_id)
            return (0, edge_collections)

    async def _collect_isoftype_targets(self, transaction: str | None, connector_id: str) -> tuple[list[dict], bool]:
        """Collect isOfType target nodes using connectorId directly."""
        if not connector_id:
            return ([], True)

        if not self.client:
            raise RuntimeError("Neo4j client not connected")

        query = """
        MATCH (record:Record {connectorId: $connector_id})-[:IS_OF_TYPE]->(typeNode)
        WITH DISTINCT typeNode, labels(typeNode) AS nodeLabels
        WHERE any(label IN nodeLabels WHERE label IN ['File', 'Mail', 'Webpage', 'Comment', 'Ticket', 'Link', 'Project', 'Meeting', 'Codefiles', 'Prs', 'Message', 'Artifact', 'Deals', 'Products'])
        RETURN {
          collection: head([label IN nodeLabels WHERE label IN ['File', 'Mail', 'Webpage', 'Comment', 'Ticket', 'Link', 'Project', 'Meeting', 'Codefiles', 'Prs', 'Message', 'Artifact', 'Deals', 'Products']]),
          key: typeNode.id,
          full_id: typeNode.id
        } AS target
        """

        try:
            results = await self.client.execute_query(
                query,
                parameters={"connector_id": connector_id},
                txn_id=transaction
            )

            targets = [result["target"] for result in results] if results else []

            self.logger.debug(f"📋 Collected {len(targets)} isOfType target nodes")

            return (targets, True)

        except Exception as e:
            self.logger.error(f"❌ Failed to collect isOfType targets: {str(e)}")
            return ([], False)

    async def _delete_isoftype_targets_from_collected(
        self,
        transaction: str,
        targets: list[dict]
    ) -> tuple[int, list[str]]:
        """Delete isOfType target nodes using pre-collected targets.

        Note: Uses DETACH DELETE which automatically removes all relationships
        connected to the nodes being deleted, so no separate edge deletion needed.
        """
        if not targets:
            return (0, [])

        if not self.client:
            raise RuntimeError("Neo4j client not connected")

        targets_by_collection: dict[str, list[str]] = {}
        for target in targets:
            coll = target["collection"]
            key = target["key"]
            if coll not in targets_by_collection:
                targets_by_collection[coll] = []
            targets_by_collection[coll].append(key)

        total_deleted = 0
        total_expected = len(targets)
        failed_collections = []

        for collection, keys in targets_by_collection.items():
            expected_count = len(keys)
            deleted, failed_batches = await self._delete_nodes_by_keys(transaction, keys, collection)
            total_deleted += deleted

            if failed_batches > 0:
                failed_collections.append(f"{collection} (failed batches: {failed_batches})")
            elif deleted < expected_count:
                failed_collections.append(f"{collection} (deleted {deleted}/{expected_count})")

        if failed_collections:
            raise Exception(
                f"CRITICAL: Failed to delete isOfType targets from {len(failed_collections)} collections: {failed_collections}. "
                f"Expected {total_expected} but deleted {total_deleted}. Transaction will be rolled back."
            )

        if total_deleted < total_expected:
            raise Exception(
                f"CRITICAL: Partial deletion of isOfType targets. Expected {total_expected} but deleted {total_deleted}. "
                f"Transaction will be rolled back."
            )

        self.logger.debug(f"✅ Deleted {total_deleted} isOfType target documents")
        return (total_deleted, [])

    async def _delete_nodes_by_keys(
        self,
        transaction: str,
        keys: list[str],
        collection: str,
        batch_size: int = 5000
    ) -> tuple[int, int]:
        """Delete documents by their ID values using batching."""
        if not keys:
            return (0, 0)

        if not self.client:
            raise RuntimeError("Neo4j client not connected")

        # Convert collection name to Neo4j label
        label = collection_to_label(collection)

        total_deleted = 0
        failed_batches = 0
        total_batches = (len(keys) + batch_size - 1) // batch_size

        for i in range(0, len(keys), batch_size):
            batch_keys = keys[i:i + batch_size]
            batch_num = (i // batch_size) + 1

            query = f"""
            MATCH (n:{label})
            WHERE n.id IN $keys
            DETACH DELETE n
            RETURN count(n) AS deleted_count
            """

            try:
                results = await self.client.execute_query(
                    query,
                    parameters={"keys": batch_keys},
                    txn_id=transaction
                )

                deleted_in_batch = results[0]["deleted_count"] if results else 0
                total_deleted += deleted_in_batch

                if deleted_in_batch < len(batch_keys):
                    self.logger.warning(
                        f"⚠️ Batch {batch_num}/{total_batches}: Only deleted {deleted_in_batch}/{len(batch_keys)} nodes from {collection}"
                    )

            except Exception as e:
                self.logger.error(f"❌ Failed to delete batch {batch_num}/{total_batches} from {collection}: {str(e)}")
                failed_batches += 1

        if failed_batches == 0:
            self.logger.info(f"✅ Deleted {total_deleted} nodes from {collection} in {total_batches} batch(es)")
        else:
            self.logger.error(f"❌ Failed {failed_batches}/{total_batches} batches for {collection}")

        return (total_deleted, failed_batches)

    async def _delete_nodes_by_connector_id(
        self,
        transaction: str,
        connector_id: str,
        collection: str
    ) -> tuple[int, bool]:
        """Delete all nodes with matching connectorId."""
        if not self.client:
            raise RuntimeError("Neo4j client not connected")

        # Convert collection name to Neo4j label
        label = collection_to_label(collection)

        query = f"""
        MATCH (n:{label} {{connectorId: $connector_id}})
        WITH count(n) AS expected_count

        MATCH (n:{label} {{connectorId: $connector_id}})
        DETACH DELETE n
        RETURN count(n) AS deleted_count
        """

        try:
            results = await self.client.execute_query(
                query,
                parameters={"connector_id": connector_id},
                txn_id=transaction
            )

            deleted_count = results[0]["deleted_count"] if results else 0

            if deleted_count > 0:
                self.logger.info(f"✅ Deleted {deleted_count} nodes from {collection} by connectorId")

            return (deleted_count, True)

        except Exception as e:
            self.logger.error(f"❌ Failed to delete nodes from {collection} by connectorId: {str(e)}")
            return (0, False)

    async def delete_sync_points_by_connector_id(
        self,
        connector_id: str,
        transaction: str | None = None
    ) -> tuple[int, bool]:
        """
        Delete all sync points for a given connector.

        Args:
            connector_id: The connector ID to delete sync points for
            transaction: Optional transaction context

        Returns:
            Tuple of (deleted_count, success_flag)
        """
        return await self._delete_nodes_by_connector_id(
            transaction=transaction,
            connector_id=connector_id,
            collection=CollectionNames.SYNC_POINTS.value
        )

    async def delete_connector_sync_edges(
        self,
        connector_id: str,
        transaction: str | None = None
    ) -> tuple[int, bool]:
        """Delete only sync-created edges for this connector. Leaves nodes and isOfType intact."""
        try:
            collected = await self._collect_connector_entities(connector_id, transaction)
            node_ids = collected.get("all_node_ids") or []
            if not node_ids:
                self.logger.debug(f"No connector entities found for {connector_id}, nothing to delete")
                return (0, True)

            deleted_count, failed = await self._delete_all_edges_for_nodes(
                transaction or "", node_ids, list(SYNC_EDGE_COLLECTIONS)
            )
            if failed:
                self.logger.warning(f"Failed to delete some sync edges for connector {connector_id}")
                return (deleted_count, False)
            self.logger.debug(f"Deleted {deleted_count} sync edges for connector {connector_id}")
            return (deleted_count, True)
        except Exception as e:
            self.logger.error(f"Error deleting connector sync edges for {connector_id}: {e}", exc_info=True)
            return (0, False)

    async def _sync_edge_rows(
        self, statement: str, collections: tuple[str, ...], node_ids: list[str],
        generation: int, transaction: str | None,
    ) -> int:
        """Run ``statement`` per node label; it sees ``n``, the edge pattern as
        ``{rel_pattern}`` and $generation, and returns ``edges`` per row."""
        keys_by_label: dict[str, list[str]] = {}
        for sid in node_ids:
            if "/" in sid:
                collection, key = sid.split("/", 1)
                keys_by_label.setdefault(collection_to_label(collection), []).append(key)
        rel_pattern = "|".join(dict.fromkeys(self._rel_pattern(c) for c in collections))
        total = 0
        for label, node_keys in keys_by_label.items():
            rows = await self.client.execute_query(
                f"MATCH (n:{label}) WHERE n.id IN $node_keys\n"
                + statement.replace("{rel_pattern}", rel_pattern),
                parameters={"node_keys": node_keys, "generation": generation},
                txn_id=transaction,
            )
            total += sum(row.get("edges", 0) or 0 for row in rows or [])
        return total

    @staticmethod
    def _on_each_sync_edge(write: str, transaction: str | None) -> str:
        """``write`` on every matched ``r``. Outside a transaction it commits in
        batches: one statement over a large connector's edges can exceed the
        transaction memory limit part way through."""
        if transaction:
            return f"{write}\n                RETURN count(r) AS edges"
        return (f"CALL (r) {{ {write} }} IN TRANSACTIONS OF {SYNC_EDGE_TAG_BATCH} ROWS\n"
                "                RETURN count(r) AS edges")

    async def mark_connector_sync_edges(
        self,
        connector_id: str,
        generation: int,
        transaction: str | None = None
    ) -> tuple[int, bool]:
        try:
            collected = await self._collect_connector_entities(connector_id, transaction)
            node_ids = collected.get("all_node_ids") or []
            if not node_ids:
                return (0, True)
            marked = await self._sync_edge_rows(
                f"""
                MATCH (n)-[r:{{rel_pattern}}]-()
                {self._on_each_sync_edge(f"SET r.{PENDING_SWEEP} = $generation", transaction)}
                """,
                SYNC_EDGE_COLLECTIONS, node_ids, generation, transaction,
            )
            return (marked, True)
        except Exception as e:
            self.logger.error(f"Error tagging sync edges of connector {connector_id}: {e}", exc_info=True)
            return (0, False)

    async def sweep_connector_sync_edges(
        self,
        connector_id: str,
        generation: int,
        transaction: str | None = None,
        keep_collections: tuple[str, ...] = (),
    ) -> tuple[int, bool]:
        try:
            collected = await self._collect_connector_entities(connector_id, transaction)
            node_ids = collected.get("all_node_ids") or []
            if not node_ids:
                return (0, True)
            written = await self._sync_edge_rows(
                f"""
                RETURN count {{
                    MATCH (n)-[r:{{rel_pattern}}]-()
                    WHERE r.{PENDING_SWEEP} IS NULL OR r.{PENDING_SWEEP} <> $generation
                }} AS edges
                """,
                SWEEP_EVIDENCE_COLLECTIONS, node_ids, generation, transaction,
            )
            if not written:
                self.logger.warning(
                    f"Full sync of {connector_id} wrote none of its edges; nothing is swept"
                )
                return (0, False)
            swept_collections = tuple(c for c in SYNC_EDGE_COLLECTIONS if c not in keep_collections)
            rel_pattern = "|".join(dict.fromkeys(self._rel_pattern(c) for c in swept_collections))
            deleted = await self._sync_edge_rows(
                f"""
                MATCH (n)-[r:{{rel_pattern}}]-(o)
                WHERE r.{PENDING_SWEEP} = $generation
                DELETE r
                {self._kh_after_edge_delete(rel_pattern, "r", "n", "o", count_as="edges")}
                """,
                swept_collections, node_ids, generation, transaction,
            )
            return (deleted, True)
        except Exception as e:
            self.logger.error(f"Error sweeping sync edges of connector {connector_id}: {e}", exc_info=True)
            return (0, False)

    async def clear_connector_sync_edge_tags(
        self,
        connector_id: str,
        generation: int,
        transaction: str | None = None
    ) -> tuple[int, bool]:
        try:
            collected = await self._collect_connector_entities(connector_id, transaction)
            node_ids = collected.get("all_node_ids") or []
            if not node_ids:
                return (0, True)
            cleared = await self._sync_edge_rows(
                f"""
                MATCH (n)-[r:{{rel_pattern}}]-()
                WHERE r.{PENDING_SWEEP} <= $generation
                {self._on_each_sync_edge(f"REMOVE r.{PENDING_SWEEP}", transaction)}
                """,
                SYNC_EDGE_COLLECTIONS, node_ids, generation, transaction,
            )
            return (cleared, True)
        except Exception as e:
            self.logger.error(f"Error clearing sync edge tags of connector {connector_id}: {e}", exc_info=True)
            return (0, False)

    async def delete_connector_instance(
        self,
        connector_id: str,
        org_id: str,
        transaction: str | None = None
    ) -> dict[str, Any]:
        """
        Delete a connector instance and all its related data with single-transaction atomicity.
        Collects data first, then deletes within a single transaction for rollback capability.
        """
        result = await self._delete_connector_instance(connector_id, org_id, transaction)
        if result.get("success"):
            try:
                await self.kh_scope_forget(connector_id)
            except Exception as e:
                self.logger.warning(f"kh scope: could not drop the scopes of deleted connector {connector_id}: {e}")
        return result

    async def _delete_connector_instance(
        self,
        connector_id: str,
        org_id: str,
        transaction: str | None = None
    ) -> dict[str, Any]:
        created_transaction = False

        try:
            self.logger.info(f"🗑️ Starting connector instance deletion for {connector_id}")

            connector = await self.get_document(
                document_key=connector_id,
                collection=CollectionNames.APPS.value
            )

            if not connector:
                return {
                    "success": False,
                    "error": f"Connector instance {connector_id} not found"
                }

            # Whether the vector cleanup will need an explicit VRID list at all.
            # Membership-based cleanup finds the points itself, so on that path
            # the list is never read and collecting it is pure cost — which is
            # the whole point on a connector with millions of records.
            needs_virtual_record_ids = not can_use_membership_cleanup(connector)

            # Phase 1: Collect data needed for return values (outside transaction)
            collected = await self._collect_connector_entities(
                connector_id,
                transaction,
                include_virtual_record_ids=needs_virtual_record_ids,
            )
            edge_collections = await self._get_all_edge_collections()

            # Collect isOfType targets before opening write transaction
            isoftype_targets, isoftype_collect_success = await self._collect_isoftype_targets(None, connector_id)
            if not isoftype_collect_success:
                return {
                    "success": False,
                    "error": "Failed to collect isOfType targets. Cannot safely delete type nodes."
                }

            self.logger.debug(
                f"📊 Collected for deletion - Records: {len(collected['record_keys'])}, "
                f"RecordGroups: {len(collected['record_group_keys'])}, Roles: {len(collected['role_keys'])}, "
                f"Groups: {len(collected['group_keys'])}, TypeNodes: {len(isoftype_targets)}"
            )

            # Phase 2: Delete within a single transaction
            node_collections = [
                CollectionNames.RECORDS.value,
                CollectionNames.RECORD_GROUPS.value,
                CollectionNames.ROLES.value,
                CollectionNames.GROUPS.value,
                CollectionNames.SYNC_POINTS.value,
                CollectionNames.FILES.value,
                CollectionNames.MAILS.value,
                CollectionNames.WEBPAGES.value,
                CollectionNames.COMMENTS.value,
                CollectionNames.TICKETS.value,
                CollectionNames.MEETINGS.value,
                CollectionNames.LINKS.value,
                CollectionNames.PROJECTS.value,
                CollectionNames.APPS.value,
            ]

            if transaction is None:
                transaction = await self.begin_transaction(
                    read=edge_collections + node_collections,
                    write=edge_collections + node_collections
                )
                created_transaction = True

            try:
                # Step 1: Delete isOfType target nodes (Files, Mails, Webpages, etc.)
                deleted_isoftype, _ = await self._delete_isoftype_targets_from_collected(
                    transaction,
                    isoftype_targets
                )

                # Step 2: Delete records
                deleted_records, failed_record_batches = await self._delete_nodes_by_keys(
                    transaction,
                    collected["record_keys"],
                    CollectionNames.RECORDS.value
                )
                if len(collected["record_keys"]) > 0 and deleted_records == 0:
                    raise Exception(
                        f"CRITICAL: Failed to delete any records. Expected {len(collected['record_keys'])} but deleted 0."
                    )

                # Step 3: Delete record groups
                deleted_rg, _ = await self._delete_nodes_by_keys(
                    transaction,
                    collected["record_group_keys"],
                    CollectionNames.RECORD_GROUPS.value
                )

                # Step 4: Delete roles
                deleted_roles, _ = await self._delete_nodes_by_keys(
                    transaction,
                    collected["role_keys"],
                    CollectionNames.ROLES.value
                )

                # Step 5: Delete groups
                deleted_groups, _ = await self._delete_nodes_by_keys(
                    transaction,
                    collected["group_keys"],
                    CollectionNames.GROUPS.value
                )

                # Step 6: Delete sync points
                deleted_sync, sync_success = await self._delete_nodes_by_connector_id(
                    transaction,
                    connector_id,
                    CollectionNames.SYNC_POINTS.value
                )
                if not sync_success:
                    raise Exception("CRITICAL: Failed to delete sync points.")

                # User -> User link is not attached to any node deleted above
                await self.remove_authenticated_as(connector_id, transaction=transaction)

                # Step 7: Delete the app itself
                deleted_app, _ = await self._delete_nodes_by_keys(
                    transaction,
                    [connector_id],
                    CollectionNames.APPS.value
                )
                if deleted_app == 0:
                    raise Exception(
                        f"CRITICAL: Failed to delete the connector app itself. Connector {connector_id} may still exist."
                    )

                # Commit transaction
                if created_transaction:
                    await self.commit_transaction(transaction)

                self.logger.debug(
                    f"✅ Connector instance {connector_id} deleted successfully. "
                    f"Records: {deleted_records}, RecordGroups: {deleted_rg}, "
                    f"Roles: {deleted_roles}, Groups: {deleted_groups}, "
                    f"isOfType targets: {deleted_isoftype}"
                )

                return {
                    "success": True,
                    "deleted_records_count": deleted_records,
                    "deleted_record_groups_count": deleted_rg,
                    "deleted_roles_count": deleted_roles,
                    "deleted_groups_count": deleted_groups,
                    "virtual_record_ids": collected["virtual_record_ids"],
                    # The connector's own record groups went with it. A point
                    # shared with a live connector survives the purge, so the
                    # cleanup needs these to strip them from recordGroupIds.
                    "record_group_ids": collected["record_group_keys"],
                    "vector_membership_backfilled": bool(
                        connector.get("vectorMembershipBackfilled", False)
                    ),
                    "vector_membership_backfill_exhausted": bool(
                        connector.get("vectorMembershipBackfillExhausted", False)
                    ),
                    "connector_id": connector_id,
                    "connector_name": connector.get("type"),
                }

            except Exception as tx_error:
                if created_transaction:
                    self.logger.error(f"🔄 Rolling back transaction due to error: {str(tx_error)}")
                    await self.rollback_transaction(transaction)
                raise tx_error

        except Exception as e:
            self.logger.error(f"❌ Failed to delete connector instance {connector_id}: {str(e)}", exc_info=True)
            return {
                "success": False,
                "error": f"Failed to delete connector instance: {str(e)}"
            }

    async def get_key_by_external_file_id(
        self,
        external_file_id: str
    ) -> str | None:
        """Get internal key by external file ID"""
        try:
            query = """
            MATCH (r:Record {externalRecordId: $external_file_id})
            RETURN r.id AS id
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"external_file_id": external_file_id}
            )

            return results[0]["id"] if results else None

        except Exception as e:
            self.logger.error(f"❌ Get key by external file ID failed: {str(e)}")
            return None

    async def get_key_by_external_message_id(
        self,
        external_message_id: str,
        transaction: str | None = None
    ) -> str | None:
        """
        Get internal key by external message ID.

        Args:
            external_message_id (str): External message ID
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Optional[str]: Internal key if found, None otherwise
        """
        try:
            self.logger.debug(
                f"🚀 Retrieving internal key for external message ID {external_message_id}"
            )

            query = """
            MATCH (r:Record {externalRecordId: $external_message_id})
            RETURN r.id AS id
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"external_message_id": external_message_id},
                txn_id=transaction
            )

            if results:
                self.logger.debug(
                    f"✅ Successfully retrieved internal key for external message ID {external_message_id}"
                )
                return results[0]["id"]
            else:
                self.logger.warning(
                    f"⚠️ No internal key found for external message ID {external_message_id}"
                )
                return None

        except Exception as e:
            self.logger.error(
                f"❌ Failed to retrieve internal key for external message ID {external_message_id}: {str(e)}"
            )
            return None

    async def get_message_id_header_by_key(
        self,
        record_key: str,
        collection: str,
        transaction: str | None = None
    ) -> str | None:
        """
        Get messageIdHeader field from a mail record by its key.

        Args:
            record_key (str): Record key (_key or id)
            collection (str): Collection name (e.g., "records" or "mails")
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Optional[str]: messageIdHeader value if found, None otherwise
        """
        try:
            self.logger.debug(
                f"🚀 Getting messageIdHeader for record {record_key} in collection {collection}"
            )

            # Map collection to Neo4j label
            label = self._get_label(collection)

            query = f"""
            MATCH (r:{label} {{id: $record_key}})
            RETURN r.messageIdHeader AS messageIdHeader
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"record_key": record_key},
                txn_id=transaction
            )

            if results and results[0].get("messageIdHeader") is not None:
                self.logger.debug(
                    f"✅ Found messageIdHeader for record {record_key}"
                )
                return results[0]["messageIdHeader"]
            else:
                self.logger.warning(
                    f"⚠️ No messageIdHeader found for record {record_key}"
                )
                return None

        except Exception as e:
            self.logger.error(
                f"❌ Failed to get messageIdHeader for record {record_key}: {str(e)}"
            )
            return None

    async def get_related_mails_by_message_id_header(
        self,
        message_id_header: str,
        exclude_key: str,
        collection: str,
        transaction: str | None = None
    ) -> list[str]:
        """
        Find all mail records with the same messageIdHeader, excluding a specific key.

        Args:
            message_id_header (str): messageIdHeader value to search for
            exclude_key (str): Record key to exclude from results
            collection (str): Collection name (e.g., "records" or "mails")
            transaction (Optional[str]): Optional transaction ID

        Returns:
            List[str]: List of record keys (_key or id) matching the criteria
        """
        try:
            self.logger.debug(
                f"🚀 Finding related mails with messageIdHeader {message_id_header}, excluding {exclude_key}"
            )

            # Map collection to Neo4j label
            label = self._get_label(collection)

            query = f"""
            MATCH (r:{label})
            WHERE r.messageIdHeader = $message_id_header
            AND r.id <> $exclude_key
            RETURN r.id AS id
            """

            results = await self.client.execute_query(
                query,
                parameters={
                    "message_id_header": message_id_header,
                    "exclude_key": exclude_key
                },
                txn_id=transaction
            )

            if results:
                self.logger.debug(
                    f"✅ Found {len(results)} related mails with messageIdHeader {message_id_header}"
                )
                return [r["id"] for r in results]
            else:
                self.logger.debug(
                    f"ℹ️ No related mails found with messageIdHeader {message_id_header}"
                )
                return []

        except Exception as e:
            self.logger.error(
                f"❌ Failed to get related mails by messageIdHeader: {str(e)}"
            )
            return []

    async def check_connector_name_uniqueness(
        self,
        instance_name: str,
        scope: str,
        org_id: str,
        user_id: str,
        collection: str,
        edge_collection: str | None = None,
        transaction: str | None = None
    ) -> bool:
        """
        Check if connector instance name is unique based on scope.

        Args:
            instance_name (str): Name to check
            scope (str): Connector scope (personal/team)
            org_id (str): Organization ID
            user_id (str): User ID (for personal scope)
            collection (str): Collection name for connector instances
            edge_collection (Optional[str]): Edge collection for org-connector relationship (for team scope)
            transaction (Optional[str]): Optional transaction ID

        Returns:
            bool: True if name is unique, False if already exists
        """
        try:
            self.logger.debug(
                f"🚀 Checking name uniqueness for '{instance_name}' with scope {scope}"
            )

            normalized_name = instance_name.strip().lower()
            label = self._get_label(collection)

            if scope == "personal":
                # For personal scope: check uniqueness within user's personal connectors
                query = f"""
                MATCH (doc:{label})
                WHERE doc.scope = $scope
                AND doc.createdBy = $user_id
                AND toLower(trim(doc.name)) = $normalized_name
                RETURN doc.id AS id
                """
                parameters = {
                    "scope": scope,
                    "user_id": user_id,
                    "normalized_name": normalized_name,
                }
            else:  # TEAM scope
                # For team scope: check uniqueness within organization's team connectors
                rel_type = self._get_relationship_type(edge_collection)
                query = f"""
                MATCH (org:Organization {{id: $org_id}})-[r:{rel_type}]->(doc:{label})
                WHERE doc.scope = $scope
                AND toLower(trim(doc.name)) = $normalized_name
                RETURN doc.id AS id
                """
                parameters = {
                    "org_id": org_id,
                    "scope": scope,
                    "normalized_name": normalized_name,
                }

            results = await self.client.execute_query(
                query,
                parameters=parameters,
                txn_id=transaction
            )

            existing = list(results) if results else []
            is_unique = len(existing) == 0

            self.logger.debug(
                f"✅ Name uniqueness check: '{instance_name}' is {'unique' if is_unique else 'not unique'}"
            )
            return is_unique

        except Exception as e:
            self.logger.error(f"❌ Error checking name uniqueness: {str(e)}")
            # On error, allow the operation (fail-open to avoid blocking)
            return True

    async def get_connector_instances_with_filters(
        self,
        collection: str,
        scope: str | None = None,
        user_id: str | None = None,
        *,
        is_admin: bool = False,
        search: str | None = None,
        page: int = 1,
        limit: int = 20,
        transaction: str | None = None,
    ) -> tuple[list[dict], int]:
        """
        Get connector instances with filters, pagination, and access control.

        Args:
            collection (str): Collection name
            scope (Optional[str]): Scope filter (personal/team)
            user_id (Optional[str]): User ID for access control
            is_admin (bool): Whether the user is an admin
            search (Optional[str]): Search query
            page (int): Page number (1-indexed)
            limit (int): Number of items per page
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Tuple[List[Dict], int]: (List of connector instances, total count)
        """
        try:
            self.logger.debug(
                f"🚀 Getting connector instances with filters: scope={scope}, search={search}, page={page}"
            )

            label = self._get_label(collection)

            # Build WHERE clauses
            where_clauses = ["doc.id IS NOT NULL"]
            parameters = {}

            # Add scope filter if specified
            if scope:
                where_clauses.append("doc.scope = $scope")
                parameters["scope"] = scope

            # Add access control
            if not is_admin:
                # Non-admins can only see their own connectors
                where_clauses.append("doc.createdBy = $user_id")
                parameters["user_id"] = user_id
            else:
                # Admins can see all team connectors + their personal connectors
                where_clauses.append("(doc.scope = $team_scope OR doc.createdBy = $user_id)")
                parameters["team_scope"] = "team"
                parameters["user_id"] = user_id

            # Add search filter if specified
            if search:
                search_pattern = f".*{search.lower()}.*"
                where_clauses.append(
                    "(toLower(doc.name) =~ $search OR toLower(doc.type) =~ $search OR toLower(doc.appGroup) =~ $search)"
                )
                parameters["search"] = search_pattern

            where_clause = " AND ".join(where_clauses)

            # Get total count
            count_query = f"""
            MATCH (doc:{label})
            WHERE {where_clause}
            RETURN count(doc) AS total
            """
            count_results = await self.client.execute_query(
                count_query,
                parameters=parameters,
                txn_id=transaction
            )
            total_count = count_results[0]["total"] if count_results else 0

            # Get paginated results
            offset = (page - 1) * limit
            parameters["offset"] = offset
            parameters["limit"] = limit

            query = f"""
            MATCH (doc:{label})
            WHERE {where_clause}
            RETURN doc
            ORDER BY doc.createdAtTimestamp DESC
            SKIP $offset
            LIMIT $limit
            """

            results = await self.client.execute_query(
                query,
                parameters=parameters,
                txn_id=transaction
            )

            documents = [self._neo4j_to_arango_node(dict(r["doc"]), collection) for r in results] if results else []

            self.logger.debug(f"✅ Found {len(documents)} connector instances (total: {total_count})")
            return documents, total_count

        except Exception as e:
            self.logger.error(f"❌ Failed to get connector instances with filters: {str(e)}")
            return [], 0

    async def count_connector_instances_by_scope(
        self,
        collection: str,
        scope: str,
        user_id: str | None = None,
        *,
        is_admin: bool = False,
        transaction: str | None = None,
    ) -> int:
        """
        Count connector instances by scope with access control.

        Args:
            collection (str): Collection name
            scope (str): Scope filter (personal/team)
            user_id (Optional[str]): User ID for access control
            is_admin (bool): Whether the user is an admin
            transaction (Optional[str]): Optional transaction ID

        Returns:
            int: Count of connector instances
        """
        try:
            self.logger.debug(f"🚀 Counting connector instances for scope {scope}")

            label = self._get_label(collection)

            where_clauses = ["doc.id IS NOT NULL", "doc.scope = $scope", "doc.isConfigured = true"]
            parameters = {"scope": scope}

            # Add user filter for personal scope
            if scope == "personal" and user_id:
                where_clauses.append("doc.createdBy = $user_id")
                parameters["user_id"] = user_id

            where_clause = " AND ".join(where_clauses)

            query = f"""
            MATCH (doc:{label})
            WHERE {where_clause}
            RETURN count(doc) AS total
            """

            results = await self.client.execute_query(
                query,
                parameters=parameters,
                txn_id=transaction
            )

            count = results[0]["total"] if results else 0
            self.logger.debug(f"✅ Found {count} connector instances for scope {scope}")
            return count

        except Exception as e:
            self.logger.error(f"❌ Failed to count connector instances by scope: {str(e)}")
            return 0

    async def get_connector_instances_by_scope_and_user(
        self,
        collection: str,
        user_id: str,
        team_scope: str,
        personal_scope: str,
        transaction: str | None = None
    ) -> list[dict]:
        """
        Get connector instances by scope and user (for _get_all_connector_instances).

        Args:
            collection (str): Collection name
            user_id (str): User ID
            team_scope (str): Team scope value
            personal_scope (str): Personal scope value
            transaction (Optional[str]): Optional transaction ID

        Returns:
            List[Dict]: List of connector instance documents
        """
        try:
            self.logger.debug(f"🚀 Getting connector instances for user {user_id}")

            label = self._get_label(collection)

            query = f"""
            MATCH (doc:{label})
            WHERE doc.id IS NOT NULL
            AND (doc.scope = $team_scope OR (doc.scope = $personal_scope AND doc.createdBy = $user_id))
            RETURN doc
            """

            parameters = {
                "team_scope": team_scope,
                "personal_scope": personal_scope,
                "user_id": user_id,
            }

            results = await self.client.execute_query(
                query,
                parameters=parameters,
                txn_id=transaction
            )

            documents = [self._neo4j_to_arango_node(dict(r["doc"]), collection) for r in results] if results else []
            self.logger.debug(f"✅ Found {len(documents)} connector instances")
            return documents

        except Exception as e:
            self.logger.error(f"❌ Failed to get connector instances by scope and user: {str(e)}")
            return []

    async def get_record_by_id(
        self,
        record_id: str,
        transaction: str | None = None
    ) -> dict | None:
        """
        Get a record by its internal ID with associated type document (file/mail/etc.).

        Args:
            record_id (str): The internal record ID to look up
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Optional[Record]: Typed Record instance (FileRecord, MailRecord, etc.) or None
        """
        try:
            self.logger.debug(f"🚀 Retrieving record for id {record_id}")

            query = """
            MATCH (record:Record {id: $record_id})
            OPTIONAL MATCH (record)-[:IS_OF_TYPE]->(typeDoc)
            RETURN record, typeDoc
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"record_id": record_id},
                txn_id=transaction
            )

            if results and len(results) > 0:
                result = results[0]
                record_dict = dict(result["record"])
                record_dict = self._neo4j_to_arango_node(record_dict, CollectionNames.RECORDS.value)

                type_doc = dict(result["typeDoc"]) if result.get("typeDoc") else None
                if type_doc:
                    type_doc = self._neo4j_to_arango_node(type_doc, "")

                typed_record = self._create_typed_record_from_neo4j(record_dict, type_doc)
                self.logger.debug(f"✅ Successfully retrieved record for id {record_id}")
                return typed_record
            else:
                self.logger.warning(f"⚠️ No record found for id {record_id}")
                return None

        except Exception as e:
            self.logger.error(f"❌ Failed to retrieve record for id {record_id}: {str(e)}")
            return None

    async def get_typed_records_batch(
        self,
        record_ids: list[str],
    ) -> dict[str, Record]:
        """
        Batch-fetch typed Record instances for the given record IDs.

        Args:
            record_ids: Internal record IDs

        Returns:
            dict[str, Record]: Mapping of record ID to typed Record instance.
            IDs not found or failing typed construction are silently omitted.
        """
        if not record_ids:
            return {}
        try:
            query = """
            UNWIND $record_ids AS rid
            MATCH (record:Record {id: rid})
            OPTIONAL MATCH (record)-[:IS_OF_TYPE]->(typeDoc)
            RETURN rid AS id, record, typeDoc
            """
            results = await self.execute_query(query, bind_vars={"record_ids": record_ids})
            typed: dict[str, Record] = {}
            for row in results or []:
                try:
                    if not row.get("record"):
                        continue
                    record_dict = dict(row["record"])
                    record_dict = self._neo4j_to_arango_node(record_dict, CollectionNames.RECORDS.value)

                    type_doc = dict(row["typeDoc"]) if row.get("typeDoc") else None
                    if type_doc:
                        type_doc = self._neo4j_to_arango_node(type_doc, "")

                    typed[row["id"]] = self._create_typed_record_from_neo4j(record_dict, type_doc)
                except Exception:
                    continue
            return typed
        except Exception as e:
            self.logger.error(f"❌ get_typed_records_batch failed: {str(e)}")
            return {}

    async def get_node_depths_batch(
        self,
        parent_id: str,
        node_ids: list[str],
        max_depth: int = 3,
        parent_type: str | None = None,
    ) -> dict[str, int]:
        if not node_ids:
            return {}
        safe_depth = max(1, min(int(max_depth), 10))
        try:
            if parent_type == "app":
                record_depth = max(1, safe_depth - 1)
                query = f"""
                CALL {{
                    MATCH (rg:RecordGroup {{connectorId: $parent_id}})
                    WHERE (rg.isDeleted IS NULL OR rg.isDeleted <> true)
                    MATCH (direct:Record)-[:BELONGS_TO]->(rg)
                    WHERE direct.id IN $node_ids
                    RETURN direct.id AS id, 1 AS level
                    UNION ALL
                    MATCH (kb_rec:Record)-[:BELONGS_TO]->(app:App {{id: $parent_id}})
                    WHERE kb_rec.id IN $node_ids
                    RETURN kb_rec.id AS id, 1 AS level
                    UNION ALL
                    MATCH (rg2:RecordGroup {{connectorId: $parent_id}})
                    WHERE (rg2.isDeleted IS NULL OR rg2.isDeleted <> true)
                    MATCH (top:Record)-[:BELONGS_TO]->(rg2)
                    MATCH path = (top)-[:NODE_RELATION*1..{record_depth}]->(desc:Record)
                    WHERE ALL(rel IN relationships(path)
                              WHERE rel.relationshipType IN ['PARENT_CHILD', 'ATTACHMENT'])
                    AND desc.id IN $node_ids
                    RETURN desc.id AS id, length(path) + 1 AS level
                }}
                RETURN id, level
                """
            elif parent_type == "recordGroup":
                record_depth = max(1, safe_depth - 1)
                query = f"""
                CALL {{
                    MATCH (direct:Record)-[:BELONGS_TO]->(rg:RecordGroup {{id: $parent_id}})
                    WHERE direct.id IN $node_ids
                    RETURN direct.id AS id, 1 AS level
                    UNION ALL
                    MATCH (top:Record)-[:BELONGS_TO]->(rg2:RecordGroup {{id: $parent_id}})
                    MATCH path = (top)-[:NODE_RELATION*1..{record_depth}]->(desc:Record)
                    WHERE ALL(rel IN relationships(path)
                              WHERE rel.relationshipType IN ['PARENT_CHILD', 'ATTACHMENT'])
                    AND desc.id IN $node_ids
                    RETURN desc.id AS id, length(path) + 1 AS level
                }}
                RETURN id, level
                """
            else:
                query = f"""
                MATCH (parent:Record {{id: $parent_id}})
                MATCH path = (parent)-[:NODE_RELATION*1..{safe_depth}]->(descendant:Record)
                WHERE ALL(rel IN relationships(path)
                          WHERE rel.relationshipType IN ['PARENT_CHILD', 'ATTACHMENT'])
                AND descendant.id IN $node_ids
                RETURN descendant.id AS id, length(path) AS level
                """
            results = await self.execute_query(
                query, bind_vars={"parent_id": parent_id, "node_ids": node_ids}
            )
            depth_map: dict[str, int] = {}
            for row in results or []:
                rid, lvl = row["id"], row["level"]
                if rid not in depth_map or lvl < depth_map[rid]:
                    depth_map[rid] = lvl
            return depth_map
        except Exception as e:
            self.logger.error(f"get_node_depths_batch failed: {e}")
            return {}

    async def check_record_access_with_details(
        self,
        user_id: str,
        org_id: str,
        record_id: str,
        transaction: str | None = None
    ) -> dict | None:
        """
        Check record access and return record details if accessible.

        Args:
            user_id (str): User ID (userId field value)
            org_id (str): Organization ID
            record_id (str): Record ID to check access for
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Optional[Dict]: Record details with permissions if accessible, None otherwise
        """
        try:
            self.logger.debug(f"🚀 Checking record access for user {user_id}, record {record_id}")

            # Get user by userId field
            user_query = """
            MATCH (u:User {userId: $user_id})
            RETURN u
            LIMIT 1
            """
            user_results = await self.client.execute_query(
                user_query,
                parameters={"user_id": user_id},
                txn_id=transaction
            )

            if not user_results:
                self.logger.warning(f"⚠️ User not found: {user_id}")
                return None

            user = dict(user_results[0]["u"])
            user_key = user.get("id")

            # The connector gate: who the user is, and the apps they may enter.
            gate = await self.get_knowledge_hub_access_context_v2(user_key, org_id, transaction=transaction)
            user_apps_ids = gate["gated_app_ids"]

            self.logger.debug(f"🚀 User apps ids: {user_apps_ids}")

            # Get record
            record = await self.get_document(record_id, CollectionNames.RECORDS.value, transaction)
            if not record:
                self.logger.warning(f"⚠️ Record not found: {record_id}")
                return None
            if not is_live_record(record):
                self.logger.info("Record %s is in the trash; no access", record_id)
                return None

            # The batch access check decides. The path query below only names how
            # access was granted (role, collection, folder) for the details, and
            # finds nothing for access that comes through inheritance or a
            # declaration it does not model. One record is decided inside its own
            # connector, and a grant is tested from the nodes the check walks
            # (`_kh_grants_by_probe`), as browsing does: resolving every grant of
            # a user who holds many would take most of the open.
            connector_id = record.get("connectorId")
            access = None
            if connector_id:
                grantees = await self._kh_v3_connector_grantees(
                    user_key, connector_id, transaction,
                ) if connector_id in user_apps_ids else []
                access = {**gate, "by_connector": {},
                          "probe": {"connector_id": connector_id, "grantees": grantees}}
            if record_id not in (await self.check_access(
                user_key, org_id, node_ids=[record_id], access=access, transaction=transaction,
            )).node_ids:
                return None

            # Build comprehensive access query
            # Check all access paths: direct, group, record group, nested record groups, org, KB.
            # Domain, "anyone" and link shares grant no access, so none is read here.
            access_query = """
            MATCH (caller:User {id: $user_key})
            MATCH (rec:Record {id: $record_id})
            WHERE rec.origin <> "CONNECTOR" OR rec.connectorId IN $user_apps_ids

            // Principals: the user, plus the source account the user authenticated this record's
            // connector as. One row per principal; their access paths are merged after the query.
            OPTIONAL MATCH (caller)-[linked:AUTHENTICATED_AS]->(source_account:User)
            WHERE linked.connectorId = rec.connectorId
            WITH caller, rec, collect(DISTINCT source_account) AS source_accounts

            // The record's record-group ancestors with their distance, walked once from
            // the record. The record-group paths below end at one of these and are
            // matched from it: matched from the user, they walked down from every
            // record group the user's groups reach to all of its descendants (millions
            // of rows) to find this one record.
            OPTIONAL MATCH kh_up = (rec)-[:INHERIT_PERMISSIONS*1..5]->(kh_anc:RecordGroup)
            WITH caller, rec, source_accounts,
                 [a IN collect(DISTINCT {node: kh_anc, depth: length(kh_up)}) WHERE a.node IS NOT NULL] AS kh_ancestors
            WITH caller, rec, source_accounts, kh_ancestors,
                 [(rec)-[:BELONGS_TO]->(kh_kb:App) WHERE kh_kb.type = "KB" AND rec.connectorName = $kb_connector_name | kh_kb] AS kh_kbs
            UNWIND [caller] + source_accounts AS u

            // Direct access
            OPTIONAL MATCH (u)-[directPerm:PERMISSION {type: "USER"}]->(rec)
            WITH u, rec, kh_ancestors, kh_kbs,
                 [x IN COLLECT({type: "DIRECT", source: u, role: directPerm.role}) WHERE x.role IS NOT NULL] AS directAccess

            // Group/Role access: User -> Group or Role -> Record
            OPTIONAL MATCH (u)-[userGroupPerm:PERMISSION {type: "USER"}]->(g)-[groupRecPerm:PERMISSION]->(rec)
            WHERE (g:Group OR g:Role)
            WITH u, rec, kh_ancestors, kh_kbs, directAccess,
                 [x IN COLLECT({type: "GROUP", source: g, role: groupRecPerm.role}) WHERE x.role IS NOT NULL] AS groupAccess

            // The record-group paths start at the ancestor the group holds the grant on
            // and only probe the principal's membership: a principal's own PERMISSION
            // edges can number tens of thousands, the groups granted on one node are few.

            // Record Group access: User -> Group or Role -> RecordGroup <- Record (INHERIT_PERMISSIONS)
            CALL (u, kh_ancestors) {
                UNWIND [a IN kh_ancestors WHERE a.depth = 1 | a.node] AS rg
                MATCH (g2)-[groupRgPerm:PERMISSION]->(rg)
                WHERE (g2:Group OR g2:Role) AND groupRgPerm.type IN ["GROUP", "ROLE"]
                  AND EXISTS { (u)-[:PERMISSION {type: "USER"}]->(g2) }
                RETURN [x IN COLLECT({type: "RECORD_GROUP", source: rg, role: groupRgPerm.role}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS recordGroupAccess
            }

            // Nested Record Group access: User -> Group or Role -> RecordGroup -> (nested RGs 2-5 levels) -> Record
            CALL (u, kh_ancestors) {
                UNWIND [a IN kh_ancestors WHERE a.depth >= 2 | a.node] AS parentRg
                MATCH (g3)-[groupParentRgPerm:PERMISSION]->(parentRg)
                WHERE (g3:Group OR g3:Role) AND groupParentRgPerm.type IN ["GROUP", "ROLE"]
                  AND EXISTS { (u)-[:PERMISSION {type: "USER"}]->(g3) }
                RETURN [x IN COLLECT(DISTINCT {type: "NESTED_RECORD_GROUP", source: parentRg, role: groupParentRgPerm.role}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS nestedRgAccess
            }

            // Direct User to Record Group access (with nested support)
            CALL (u, kh_ancestors) {
                UNWIND [a IN kh_ancestors | a.node] AS rg2
                MATCH (u)-[userRgPerm:PERMISSION {type: "USER"}]->(rg2)
                RETURN [x IN COLLECT(DISTINCT {type: "DIRECT_USER_RECORD_GROUP", source: rg2, role: userRgPerm.role}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS directUserRgAccess
            }

            // Inherited RecordGroup permission: Record -> RecordGroup hierarchy (OUTBOUND), then User -> RecordGroup
            // Traverse UP from record to find RecordGroups in hierarchy, then check if user has direct permission
            OPTIONAL MATCH (rec)-[:INHERIT_PERMISSIONS*0..5]->(inheritedRg:RecordGroup)
            OPTIONAL MATCH (u)-[inheritedRgPerm:PERMISSION {type: "USER"}]->(inheritedRg)
            WITH u, rec, kh_ancestors, kh_kbs, directAccess, groupAccess, recordGroupAccess, nestedRgAccess, directUserRgAccess,
                 [x IN COLLECT({type: "INHERITED_RECORD_GROUP", source: inheritedRg, role: inheritedRgPerm.role}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS inheritedRgAccess

            // Group/Role Inherited RecordGroup permission: Record -> RecordGroup hierarchy (OUTBOUND), then User -> Group or Role -> RecordGroup
            CALL (u, kh_ancestors) {
                UNWIND [a IN kh_ancestors WHERE a.depth >= 2 | a.node] AS inheritedRg2
                MATCH (g4)-[groupInheritedRgPerm:PERMISSION]->(inheritedRg2)
                WHERE (g4:Group OR g4:Role) AND groupInheritedRgPerm.type IN ["GROUP", "ROLE"]
                  AND EXISTS { (u)-[:PERMISSION {type: "USER"}]->(g4) }
                RETURN [x IN COLLECT({type: "GROUP_INHERITED_RECORD_GROUP", source: inheritedRg2, role: groupInheritedRgPerm.role}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS groupInheritedRgAccess
            }

            // Organization access: User -> Organization -> Record
            OPTIONAL MATCH (u)-[:BELONGS_TO]->(org:Organization {id: $org_id})-[orgRecPerm:PERMISSION]->(rec5:Record {id: $record_id})
            WHERE orgRecPerm.type IN $org_share_types
              AND (rec5.origin <> "CONNECTOR" OR rec5.connectorId IN $user_apps_ids)
            WITH u, rec, kh_ancestors, kh_kbs, directAccess, groupAccess, recordGroupAccess, nestedRgAccess, directUserRgAccess, inheritedRgAccess, groupInheritedRgAccess,
                 [x IN COLLECT({type: "ORGANIZATION", source: org, role: orgRecPerm.role}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS orgAccess

            // Organization Record Group access: User -> Organization -> RecordGroup -> Record
            CALL (u, kh_ancestors) {
                UNWIND [a IN kh_ancestors WHERE a.depth <= 2 | a.node] AS rg3
                MATCH (u)-[belongsTo:BELONGS_TO {entityType: "ORGANIZATION"}]->(org2:Organization {id: $org_id})-[orgRgPerm:PERMISSION {type: "ORG"}]->(rg3)
                RETURN [x IN COLLECT(DISTINCT {type: "ORG_RECORD_GROUP", source: rg3, role: orgRgPerm.role}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS orgRgAccess
            }

            // Knowledge Base access: KB is now an App node (type = "KB")
            CALL (u, kh_kbs) {
                UNWIND kh_kbs AS kb
                MATCH (u)-[kbPerm:PERMISSION {type: "USER"}]->(kb)
                RETURN [x IN COLLECT({type: "KNOWLEDGE_BASE", source: kb, role: kbPerm.role, folder: null}) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS kbDirectAccess
            }

            // KB Team access: Only for KB records, not connector records
            CALL (u, kh_kbs) {
                UNWIND kh_kbs AS kb2
                MATCH (team:Teams)-[teamKbPerm:PERMISSION {type: "TEAM"}]->(kb2)
                WITH u, kb2, collect(DISTINCT team) AS kh_teams
                UNWIND kh_teams AS team
                MATCH (u)-[userTeamPerm:PERMISSION {type: "USER"}]->(team)
                RETURN [x IN COLLECT({
                     type: "KNOWLEDGE_BASE_TEAM",
                     source: kb2,
                     role: userTeamPerm.role,
                     folder: null
                 }) WHERE x.source IS NOT NULL AND x.role IS NOT NULL] AS kbTeamAccess
            }

            // For KB records, collect KB RecordGroup source IDs to deduplicate generic RG access paths
            WITH directAccess, groupAccess, recordGroupAccess, nestedRgAccess, directUserRgAccess, inheritedRgAccess, groupInheritedRgAccess, orgAccess, orgRgAccess, kbDirectAccess, kbTeamAccess,
                 [kb IN (kbDirectAccess + kbTeamAccess) WHERE kb.source IS NOT NULL | kb.source.id] AS kbSourceIds

            // Filter out generic RecordGroup entries that redundantly match the same KB RecordGroup
            WITH directAccess, groupAccess,
                 [x IN recordGroupAccess WHERE NOT x.source.id IN kbSourceIds] AS recordGroupAccess,
                 [x IN nestedRgAccess WHERE NOT x.source.id IN kbSourceIds] AS nestedRgAccess,
                 [x IN directUserRgAccess WHERE NOT x.source.id IN kbSourceIds] AS directUserRgAccess,
                 [x IN inheritedRgAccess WHERE NOT x.source.id IN kbSourceIds] AS inheritedRgAccess,
                 [x IN groupInheritedRgAccess WHERE NOT x.source.id IN kbSourceIds] AS groupInheritedRgAccess,
                 orgAccess, orgRgAccess, kbDirectAccess, kbTeamAccess

            // Combine all access paths
            WITH directAccess, groupAccess, recordGroupAccess, nestedRgAccess, directUserRgAccess, inheritedRgAccess, groupInheritedRgAccess, orgAccess, orgRgAccess, kbDirectAccess, kbTeamAccess,
                 directAccess + groupAccess + recordGroupAccess + nestedRgAccess + directUserRgAccess + inheritedRgAccess + groupInheritedRgAccess + orgAccess + orgRgAccess + kbDirectAccess + kbTeamAccess AS allAccess
            WHERE size([a IN allAccess WHERE a.source IS NOT NULL]) > 0
            RETURN allAccess, directAccess, groupAccess, recordGroupAccess, nestedRgAccess, directUserRgAccess, inheritedRgAccess, groupInheritedRgAccess, orgAccess, orgRgAccess, kbDirectAccess, kbTeamAccess
            """

            access_results = await self.client.execute_query(
                access_query,
                parameters={
                    "user_key": user_key,
                    "record_id": record_id,
                    "org_id": org_id,
                    "user_apps_ids": user_apps_ids,
                    "kb_connector_name": Connectors.KNOWLEDGE_BASE.value,
                    "org_share_types": list(ORG_SHARE_PERMISSION_TYPES),
                },
                txn_id=transaction
            )

            # One row per principal: the user and, through a link, the source account.
            access_result = [access for row in access_results or [] for access in (row.get("allAccess") or [])]
            # Filter out None entries
            access_result = [a for a in access_result if a.get("source") is not None]
            if not access_result:
                # Connector items carry no role; what the check admitted is read
                # access, and the UI shows a null role as Owner.
                access_result = [{"type": "CONNECTOR", "role": "READER"}]

            # Get additional data based on record type
            additional_data = None
            record_type = record.get("recordType")

            if record_type == RecordTypes.FILE.value:
                additional_data = await self.get_document(
                    record_id, CollectionNames.FILES.value, transaction
                )
            elif record_type == RecordTypes.MAIL.value:
                additional_data = await self.get_document(
                    record_id, CollectionNames.MAILS.value, transaction
                )
            elif record_type == RecordTypes.TICKET.value:
                additional_data = await self.get_document(
                    record_id, CollectionNames.TICKETS.value, transaction
                )

            connector_name = record.get("connectorName")
            if additional_data and additional_data.get("webUrl"):
                additional_data["webUrl"] = substitute_user_email(
                    additional_data["webUrl"], user.get("email"), connector_name
                )

            # Get metadata (departments, categories, topics, languages)
            # Use separate queries to avoid aggregation conflicts
            # Note: Labels use capitalized collection names (Departments, Categories, etc.)
            metadata_query = """
            MATCH (rec:Record {id: $record_id})

            OPTIONAL MATCH (rec)-[:BELONGS_TO_DEPARTMENT]->(dept:Departments)
            WITH rec, COLLECT(DISTINCT {id: dept.id, name: dept.departmentName}) AS departments

            OPTIONAL MATCH (rec)-[catLink:BELONGS_TO_CATEGORY]->(cat:Categories)
            WITH rec, departments, COLLECT(DISTINCT {id: cat.id, name: cat.name, extractedName: catLink.extractedName, extractedNames: catLink.extractedNames, canonical: cat.normalizedName IS NOT NULL, migrated: catLink.migratedFrom IS NOT NULL}) AS categories

            OPTIONAL MATCH (rec)-[sub1Link:BELONGS_TO_CATEGORY]->(subcat1:Subcategories1)
            WITH rec, departments, categories, COLLECT(DISTINCT {id: subcat1.id, name: subcat1.name, extractedName: sub1Link.extractedName, extractedNames: sub1Link.extractedNames, canonical: subcat1.normalizedName IS NOT NULL, migrated: sub1Link.migratedFrom IS NOT NULL}) AS subcategories1

            OPTIONAL MATCH (rec)-[sub2Link:BELONGS_TO_CATEGORY]->(subcat2:Subcategories2)
            WITH rec, departments, categories, subcategories1, COLLECT(DISTINCT {id: subcat2.id, name: subcat2.name, extractedName: sub2Link.extractedName, extractedNames: sub2Link.extractedNames, canonical: subcat2.normalizedName IS NOT NULL, migrated: sub2Link.migratedFrom IS NOT NULL}) AS subcategories2

            OPTIONAL MATCH (rec)-[sub3Link:BELONGS_TO_CATEGORY]->(subcat3:Subcategories3)
            WITH rec, departments, categories, subcategories1, subcategories2, COLLECT(DISTINCT {id: subcat3.id, name: subcat3.name, extractedName: sub3Link.extractedName, extractedNames: sub3Link.extractedNames, canonical: subcat3.normalizedName IS NOT NULL, migrated: sub3Link.migratedFrom IS NOT NULL}) AS subcategories3

            OPTIONAL MATCH (rec)-[topicLink:BELONGS_TO_TOPIC]->(topic:Topics)
            WITH rec, departments, categories, subcategories1, subcategories2, subcategories3, COLLECT(DISTINCT {id: topic.id, name: topic.name, extractedName: topicLink.extractedName, extractedNames: topicLink.extractedNames, canonical: topic.normalizedName IS NOT NULL, migrated: topicLink.migratedFrom IS NOT NULL}) AS topics

            OPTIONAL MATCH (rec)-[langLink:BELONGS_TO_LANGUAGE]->(lang:Languages)
            WITH departments, categories, subcategories1, subcategories2, subcategories3, topics, COLLECT(DISTINCT {id: lang.id, name: lang.name, extractedName: langLink.extractedName, extractedNames: langLink.extractedNames, canonical: lang.normalizedName IS NOT NULL, migrated: langLink.migratedFrom IS NOT NULL}) AS languages

            RETURN {
                departments: [d IN departments WHERE d.id IS NOT NULL],
                categories: [c IN categories WHERE c.id IS NOT NULL],
                subcategories1: [s1 IN subcategories1 WHERE s1.id IS NOT NULL],
                subcategories2: [s2 IN subcategories2 WHERE s2.id IS NOT NULL],
                subcategories3: [s3 IN subcategories3 WHERE s3.id IS NOT NULL],
                topics: [t IN topics WHERE t.id IS NOT NULL],
                languages: [l IN languages WHERE l.id IS NOT NULL]
            } AS metadata
            """

            metadata_results = await self.client.execute_query(
                metadata_query,
                parameters={"record_id": record_id},
                txn_id=transaction
            )
            metadata_result = own_record_labels(
                metadata_results[0].get("metadata") if metadata_results else None
            )

            # Get knowledge base info if record is in a KB
            kb_info = None
            folder_info = None
            for access in access_result:
                if access.get("type") in ["KNOWLEDGE_BASE", "KNOWLEDGE_BASE_TEAM"]:
                    kb = access.get("source")
                    if kb:
                        kb_info = {
                            "id": kb.get("id") or kb.get("_key"),
                            "name": kb.get("name"),
                            "orgId": kb.get("orgId"),
                        }
                    folder = access.get("folder")
                    if folder:
                        folder_info = {
                            "id": folder.get("id") or folder.get("_key"),
                            "name": folder.get("name")
                        }
                    break

            # Select the highest permission from all access paths
            role_priority = {"OWNER": 3, "WRITER": 2, "READER": 1}

            best_access = max(
                access_result,
                key=lambda a: role_priority.get(read_role(a.get("role", "")), 0)
            )

            permissions = [{
                "id": record.get("id") or record.get("_key"),
                "name": record.get("recordName"),
                "type": record.get("recordType"),
                "relationship": read_role(best_access.get("role")),
                "accessType": best_access.get("type"),
            }]

            record["id"] = record.pop("_key")
            if record.get("webUrl"):
                record["webUrl"] = substitute_user_email(
                    record["webUrl"], user.get("email"), connector_name
                )
            return {
                "record": {
                    **record,
                    "fileRecord": (
                        additional_data
                        if record_type == RecordTypes.FILE.value
                        else None
                    ),
                    "mailRecord": (
                        additional_data
                        if record_type == RecordTypes.MAIL.value
                        else None
                    ),
                    "ticketRecord": (
                        additional_data
                        if record_type == RecordTypes.TICKET.value
                        else None
                    ),
                },
                "knowledgeBase": kb_info,
                "folder": folder_info,
                "metadata": metadata_result,
                "permissions": permissions,
            }

        except Exception as e:
            self.logger.error(f"❌ Failed to check record access: {str(e)}")
            raise

    async def get_account_type(
        self,
        org_id: str,
        is_external: bool = False,
        transaction: str | None = None
    ) -> str | None:
        """
        Get account type for an organization.

        Args:
            org_id (str): Organization ID
            is_external (bool): Filter by external flag (default False)
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Optional[str]: Account type (e.g., "INDIVIDUAL", "ENTERPRISE") or None
        """
        try:
            self.logger.debug(f"🚀 Getting account type for organization {org_id}")

            if is_external:
                external_filter = "o.isExternal = true"
            else:
                external_filter = "(o.isExternal = false OR o.isExternal IS NULL)"

            query = f"""
            MATCH (o:Organization {{id: $org_id}})
            WHERE {external_filter}
            RETURN o.accountType AS accountType
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"org_id": org_id},
                txn_id=transaction
            )

            if results:
                account_type = results[0].get("accountType")
                self.logger.debug(f"✅ Found account type: {account_type}")
                return account_type
            else:
                self.logger.warning(f"⚠️ Organization not found: {org_id}")
                return None

        except Exception as e:
            self.logger.error(f"❌ Failed to get account type: {str(e)}")
            return None

    async def get_connector_stats(
        self,
        org_id: str,
        connector_id: str,
        transaction: str | None = None
    ) -> dict:
        """
        Get connector statistics for a specific connector or KB collection.

        Args:
            org_id (str): Organization ID
            connector_id (str): Connector ID (or KB app ID)
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Dict: Statistics data with success status
        """
        statuses = [s.value for s in ProgressStatus]
        try:
            self.logger.debug(f"🚀 Getting connector stats for org {org_id}, connector {connector_id}")

            # Detect whether this id is a KB collection (records link directly to the
            # App node) or an external connector (records link via a RecordGroup). Only
            # the linkage differs, so one query body is shared and the MATCH swapped in.
            app_query = "MATCH (app:App {id: $connector_id}) RETURN app.type AS type"
            app_result = await self.client.execute_query(
                app_query,
                parameters={"connector_id": connector_id},
                txn_id=transaction
            )
            is_kb = bool(app_result) and app_result[0].get("type") == Connectors.KNOWLEDGE_BASE.value
            self.logger.debug(f"📊 Computing {'KB collection' if is_kb else 'external connector'} stats for {connector_id}")

            # Only records reached from the App count: a group cut off from it and
            # its records stay out. A record in several groups (a Drive file and a
            # sharee's Shared-with-Me group) counts once. A folder is told by the
            # record's own mimeType, not a hop to its File node.
            linkage = (
                "MATCH (:App {id: $connector_id})<-[:BELONGS_TO]-(r:Record)"
                if is_kb
                else "MATCH (:App {id: $connector_id})<-[:BELONGS_TO*1..10]-(:RecordGroup)"
                     "<-[:BELONGS_TO]-(r:Record)"
            )

            query = f"""
            {linkage}
            WHERE coalesce(r.isInternal, false) = false
              AND coalesce(r.isPlaceholder, false) = false
              AND coalesce(r.isDeleted, false) = false
              AND NOT coalesce(r.mimeType, '') IN $folder_mime_types
            RETURN r.recordType AS recordType, r.indexingStatus AS indexingStatus, count(DISTINCT r) AS cnt
            """

            results = await self.client.execute_query(
                query,
                parameters={
                    "connector_id": connector_id,
                    "folder_mime_types": FOLDER_MIME_TYPES,
                },
                txn_id=transaction
            )

            rows = results or []
            origin = "COLLECTION" if is_kb else "CONNECTOR"
            result = build_connector_stats_response(rows, statuses, org_id, connector_id, origin=origin)

            self.logger.debug(f"✅ Retrieved stats for connector {connector_id}")
            return {
                "success": True,
                "data": result
            }

        except Exception as e:
            self.logger.error(f"❌ Failed to get connector stats: {str(e)}")
            return {
                "success": False,
                "message": str(e),
                "data": None
            }

    async def reindex_single_record(
        self,
        record_id: str,
        user_id: str,
        org_id: str,
        request: Request,
        depth: int = 0,
        status_filters: list[str] | None = None,
    ) -> dict:
        """
        Reindex a single record with permission checks and event publishing.
        Depth comes from caller: 0 = only this record (record-details, collections/KB);
        >0 = include children (e.g. all-records tree uses 100).
        - KB (UPLOAD): depth > 0 uses sync-events; depth == 0 uses record-events.
        - CONNECTOR: uses sync-events and honors depth.

        Args:
            record_id: Record ID to reindex
            user_id: External user ID doing the reindex
            org_id: Organization ID
            request: FastAPI request object
            depth: Depth for children (0 = only this record; -1 or >MAX = normalized to MAX_REINDEX_DEPTH)

        Returns:
            Dict: success, recordId, recordName, connector, eventPublished, userRole; or error code/reason
        """
        try:
            self.logger.debug(f"🔄 Starting reindex for record {record_id} by user {user_id} with depth {depth}")

            # Normalize depth only when including children (-1 or >MAX -> MAX_REINDEX_DEPTH); depth 0 stays 0
            if depth != 0 and (depth == -1 or depth > MAX_REINDEX_DEPTH):
                depth = MAX_REINDEX_DEPTH

            # Get record to determine connector type
            record = await self.get_document(record_id, CollectionNames.RECORDS.value)
            if not record:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"Record not found: {record_id}"
                }

            if record.get("isDeleted"):
                return {
                    "success": False,
                    "code": 400,
                    "reason": "Cannot reindex deleted record"
                }

            connector_name = record.get("connectorName", "")
            connector_id = record.get("connectorId", "")
            origin = record.get("origin", "")

            self.logger.debug(f"📋 Record details - Origin: {origin}, Connector: {connector_name}, ConnectorId: {connector_id}")

            # Get user
            user = await self.get_user_by_user_id(user_id)
            if not user:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"User not found: {user_id}"
                }

            user_key = user.get('_key') or user.get('id')
            if not user_key:
                return {"success": False, "code": 404, "reason": "User key not found"}

            user_role = None

            # Check permissions based on origin type
            if origin == OriginTypes.UPLOAD.value:
                # KB record - check KB permissions
                kb_context = await self._get_kb_context_for_record(record_id)
                if not kb_context:
                    return {
                        "success": False,
                        "code": 404,
                        "reason": f"Knowledge base context not found for record {record_id}"
                    }

                user_role = await self.get_user_kb_permission(kb_context.get("kb_id") or kb_context.get("id"), user_key)
                if not user_role:
                    return {
                        "success": False,
                        "code": 403,
                        "reason": "Insufficient KB permissions. Required: OWNER, WRITER, READER"
                    }

            elif origin == OriginTypes.CONNECTOR.value:
                # Anyone who may access the record may reindex it: connector
                # items carry no role.
                if record_id not in (await self.check_access(
                    user_key, org_id, node_ids=[record_id],
                )).node_ids:
                    return {
                        "success": False,
                        "code": 403,
                        "reason": "You do not have access to this record"
                    }

                # Check if connector is enabled before allowing reindex
                if connector_id:
                    connector_doc = await self.get_document(connector_id, CollectionNames.APPS.value)
                    if connector_doc and not connector_doc.get("isActive", False):
                        display_name = connector_doc.get("name", "connector")
                        return {
                            "success": False,
                            "code": 409,
                            "reason": f"The connector '{display_name}' is currently disabled. Enable it from Connector Settings and try again."
                        }
            else:
                return {
                    "success": False,
                    "code": 400,
                    "reason": f"Unsupported record origin: {origin}"
                }


            # Create event data for router to publish
            try:
                if origin == OriginTypes.UPLOAD.value and depth > 0:
                    # KB folder reindex with children: use sync-events (same as connectors)
                    # Consumer will find children via get_records_by_parent_record(depth)
                    connector_for_event = connector_name.replace(" ", "").lower() if connector_name else "kb"
                    event_type = f"{connector_for_event}.reindex"

                    payload = {
                        "orgId": org_id,
                        "recordId": record_id,
                        "depth": depth,
                        "connectorId": connector_id,
                        "connector": connector_for_event,
                        "userKey": user_key,
                    }
                    if status_filters:
                        payload["statusFilters"] = status_filters

                    event_data = {
                        "eventType": event_type,
                        "topic": "sync-events",
                        "payload": payload
                    }
                elif origin == OriginTypes.UPLOAD.value:
                    # Single KB file reindex: use record-events
                    file_record = None
                    if record.get("recordType") == "FILE":
                        file_record = await self.get_document(record_id, CollectionNames.FILES.value)

                    payload = await self._create_reindex_event_payload(record, file_record, user_id, request, record_id=record_id)
                    event_data = {
                        "eventType": "newRecord",
                        "topic": "record-events",
                        "payload": payload
                    }
                    # Clear any terminal status so the consumer's COMPLETED gate does not
                    # skip the event. The router promotes this to QUEUED once it publishes.
                    await self.update_indexing_status_for_record_ids(
                        [record_id], ProgressStatus.NOT_STARTED.value
                    )
                else:
                    # For connector records, use sync-events with connector reindex event
                    connector_for_event = connector_name.replace(" ", "").lower() if connector_name else "unknown"
                    event_type = f"{connector_for_event}.reindex"

                    payload = {
                        "orgId": org_id,
                        "recordId": record_id,
                        "depth": depth,
                        "connectorId": connector_id,
                        "connector": connector_for_event,  # Add connector field for consumer fallback
                        "userKey": user_key,
                    }
                    if status_filters:
                        payload["statusFilters"] = status_filters

                    event_data = {
                        "eventType": event_type,
                        "topic": "sync-events",
                        "payload": payload
                    }

                return {
                    "success": True,
                    "recordId": record_id,
                    "recordName": record.get("recordName"),
                    "connector": connector_name if origin == OriginTypes.CONNECTOR.value else Connectors.KNOWLEDGE_BASE.value,
                    "userRole": user_role,
                    "eventData": event_data,
                    "useBatchReindex": origin != OriginTypes.UPLOAD.value  # KB records don't use batch reindex
                }

            except Exception as event_error:
                self.logger.error(f"❌ Failed to create reindex event data: {str(event_error)}")
                # Return success but indicate event data creation failed
                return {
                    "success": True,
                    "recordId": record_id,
                    "recordName": record.get("recordName"),
                    "connector": connector_name if origin == OriginTypes.CONNECTOR.value else Connectors.KNOWLEDGE_BASE.value,
                    "userRole": user_role,
                    "eventData": None,
                    "eventError": str(event_error)
                }

        except Exception as e:
            self.logger.error(f"❌ Failed to reindex record {record_id}: {str(e)}")
            return {"success": False, "code": 500, "reason": str(e)}

    async def reindex_record_group_records(
        self,
        record_group_id: str,
        depth: int,
        user_id: str,
        org_id: str
    ) -> dict:
        """
        Get record group data and validate permissions for reindexing.
        Does NOT publish events - that should be done by the caller (router).

        Args:
            record_group_id: Record group ID
            depth: Depth for traversing children (0 = only direct records)
            user_id: External user ID doing the reindex
            org_id: Organization ID

        Returns:
            Dict: Result with success status and connector information
        """
        try:
            self.logger.debug(f"🔄 Validating record group reindex for {record_group_id} with depth {depth} by user {user_id}")

            # Handle negative depth: -1 means unlimited (set to MAX_REINDEX_DEPTH), other negatives are invalid (set to 0)
            if depth == -1:
                depth = MAX_REINDEX_DEPTH
                self.logger.debug(f"Depth was -1 (unlimited), setting to maximum limit: {depth}")
            elif depth < 0:
                self.logger.warning(f"Invalid negative depth {depth}, setting to 0 (direct records only)")
                depth = 0

            # Get record group
            record_group = await self.get_document(record_group_id, CollectionNames.RECORD_GROUPS.value)
            if not record_group:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"Record group not found: {record_group_id}"
                }

            connector_id = record_group.get("connectorId", "")
            connector_name = record_group.get("connectorName", "")
            if not connector_id or not connector_name:
                return {
                    "success": False,
                    "code": 400,
                    "reason": "Record group does not have a connector id or name"
                }

            # Get user
            user = await self.get_user_by_user_id(user_id)
            if not user:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"User not found: {user_id}"
                }

            user_key = user.get('_key') or user.get('id')
            if not user_key:
                return {"success": False, "code": 404, "reason": "User key not found"}

            try:
                allowed = record_group_id in (await self.check_access(
                    user_key, org_id, node_ids=[record_group_id],
                )).node_ids
            except Exception:
                self.logger.exception("❌ Access check failed for record group %s", record_group_id)
                return {"success": False, "code": 500, "reason": action_failed("check access to this record group")}
            if not allowed:
                return {
                    "success": False,
                    "code": 403,
                    "reason": "You do not have access to this record group"
                }

            # After the access check: the 409 names the connector.
            connector_doc = await self.get_document(connector_id, CollectionNames.APPS.value)
            if connector_doc and not connector_doc.get("isActive", False):
                display_name = connector_doc.get("name", "connector")
                return {
                    "success": False,
                    "code": 409,
                    "reason": f"The connector '{display_name}' is currently disabled. Enable it from Connector Settings and try again."
                }

            # Return success with connector information (caller will publish event)
            return {
                "success": True,
                "connectorId": connector_id,
                "connectorName": connector_name,
                "depth": depth,
                "recordGroupId": record_group_id,
                "userKey": user_key
            }

        except Exception as e:
            self.logger.error("❌ Failed to validate record group reindex: %s", str(e))
            return {"success": False, "code": 500, "reason": str(e)}

    async def organization_exists(
        self,
        organization_name: str,
        is_external: bool = False,
    ) -> bool:
        """Check if an organization exists"""
        try:
            if is_external:
                external_filter = "o.isExternal = true"
            else:
                external_filter = "(o.isExternal = false OR o.isExternal IS NULL)"

            query = f"""
            MATCH (o:Organization {{name: $organization_name}})
            WHERE {external_filter}
            RETURN o.id
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"organization_name": organization_name}
            )

            return bool(results)

        except Exception as e:
            self.logger.error(f"❌ Organization exists check failed: {str(e)}")
            return False

    async def get_user_sync_state(
        self,
        user_email: str,
        service_type: str,
        transaction: str | None = None
    ) -> dict | None:
        """Get user's sync state for a specific service"""
        try:
            query = """
            MATCH (u:User {email: $user_email})-[rel:USER_APP_RELATION]->(app:App {name: $service_type})
            RETURN rel, u.id AS from_id, app.id AS to_id
            LIMIT 1
            """

            results = await self.client.execute_query(
                query,
                parameters={"user_email": user_email, "service_type": service_type},
                txn_id=transaction
            )

            if results:
                rel = dict(results[0]["rel"])
                # Return in generic format
                rel["from_id"] = results[0]["from_id"]
                rel["from_collection"] = CollectionNames.USERS.value
                rel["to_id"] = results[0]["to_id"]
                rel["to_collection"] = CollectionNames.APPS.value
                return rel

            return None

        except Exception as e:
            self.logger.error(f"❌ Get user sync state failed: {str(e)}")
            return None

    async def update_user_sync_state(
        self,
        user_email: str,
        state: str,
        service_type: str,
        transaction: str | None = None
    ) -> dict | None:
        """Update user's sync state for a specific service"""
        try:
            updated_timestamp = get_epoch_timestamp_in_ms()

            query = """
            MATCH (u:User {email: $user_email})-[rel:USER_APP_RELATION]->(app:App {name: $service_type})
            SET rel.syncState = $state, rel.lastSyncUpdate = $updated_timestamp
            RETURN rel, u.id AS from_id, app.id AS to_id
            """

            results = await self.client.execute_query(
                query,
                parameters={
                    "user_email": user_email,
                    "service_type": service_type,
                    "state": state,
                    "updated_timestamp": updated_timestamp
                },
                txn_id=transaction
            )

            if results:
                rel = dict(results[0]["rel"])
                # Return in generic format
                rel["from_id"] = results[0]["from_id"]
                rel["from_collection"] = CollectionNames.USERS.value
                rel["to_id"] = results[0]["to_id"]
                rel["to_collection"] = CollectionNames.APPS.value
                return rel

            return None

        except Exception as e:
            self.logger.error(f"❌ Update user sync state failed: {str(e)}")
            return None

